from gurobipy import GRB
shelves = []
capacities = {}
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('capacity.csv'):
        shelf = rec['values']['ShelfID']
        shelves.append(shelf)
        capacities[shelf] = int(rec['values']['Capacity'])
products = []
values = {}
weights = {}
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('products.csv'):
        prod = rec['values']['ProductName']
        products.append(prod)
        values[prod] = int(rec['values']['Value'])
        weights[prod] = int(rec['values']['Weight'])
if len(shelves) == 0 or len(products) == 0:
    raise ValueError('Missing shelves or products data.')
for shelf in shelves:
    if shelf not in capacities:
        raise ValueError(f'Missing capacity for shelf {shelf}.')
for prod in products:
    if prod not in values or prod not in weights:
        raise ValueError(f'Missing value or weight for product {prod}.')
